@push('scripts')
<script>
$(function(){
    const form=$('#kanban-filter'),columns=$('.crm-kanban-column'),dataUrl=@json(route('crm.opportunities.kanban.data')),transitionUrl=@json(route('crm.opportunities.stage',['opportunity'=>'__ID__'])),indexUrl=@json(route('crm.opportunities.kanban')),stages=@json(collect($stages)->map(fn($stage)=>['label'=>$stage['label']])->all()),csrf=$('meta[name="csrf-token"]').attr('content');let requests={};
    const owner=$('.js-kanban-owner');window.erpInitSelect2(owner,{theme:'bootstrap-5',placeholder:'ผู้รับผิดชอบทุกคน',allowClear:true,ajax:{url:owner.data('url'),dataType:'json',delay:250,data:p=>({q:p.term||'',page:p.page||1}),processResults:d=>d}});
    function load(column,page,append){const stage=column.data('stage');if(requests[stage])requests[stage].abort();const params=new URLSearchParams(new FormData(form[0]));params.set('stage',stage);params.set('page',page);const items=column.find('.crm-kanban-items'),more=column.find('.js-load-more');if(!append)items.html('<div class="text-center text-secondary py-4"><span class="spinner-border spinner-border-sm"></span></div>');more.addClass('d-none');requests[stage]=$.getJSON(dataUrl,params.toString()).done(function(data){if(append)items.append(data.html);else items.html(data.html||'<div class="crm-kanban-empty">ไม่มี Opportunity</div>');column.find('.js-stage-count').text(Number(data.total).toLocaleString('th-TH'));more.toggleClass('d-none',!data.next_page).data('next-page',data.next_page||'');}).fail(function(xhr,status){if(status!=='abort'&&!append)items.html('<div class="alert alert-danger small">โหลดข้อมูลไม่สำเร็จ</div>');});}
    function loadAll(push){columns.each(function(){load($(this),1,false);});if(push){const params=new URLSearchParams(new FormData(form[0]));history.pushState({},'',indexUrl+(params.toString()?'?'+params.toString():''));}}
    async function chooseStage(card){const options={};Object.entries(stages).forEach(([code,stage])=>{if(code!==card.data('stage'))options[code]=stage.label;});const result=await Swal.fire({title:'เปลี่ยนขั้นตอน',text:card.data('title'),input:'select',inputOptions:options,inputPlaceholder:'เลือกขั้นตอนใหม่',showCancelButton:true,confirmButtonText:'ถัดไป',cancelButtonText:'ยกเลิก',inputValidator:value=>!value?'กรุณาเลือกขั้นตอน':null});if(result.isConfirmed)transition(card,result.value);}
    async function transition(card,stage){if(!stage||stage===card.data('stage'))return;let values={stage};if(stage==='LOST'){const result=await Swal.fire({icon:'warning',title:'ระบุเหตุผลที่ไม่สำเร็จ',input:'textarea',inputPlaceholder:'เหตุผลอย่างน้อย 5 ตัวอักษร',showCancelButton:true,confirmButtonText:'บันทึกว่าไม่สำเร็จ',cancelButtonText:'ยกเลิก',inputValidator:value=>!value||value.trim().length<5?'กรุณาระบุเหตุผลอย่างน้อย 5 ตัวอักษร':null});if(!result.isConfirmed)return;values.lost_reason=result.value.trim();}else if(stage==='WON'){const today=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10),result=await Swal.fire({icon:'success',title:'ข้อมูลปิดการขาย',html:'<label class="form-label d-block text-start" for="swal-won-value">มูลค่าปิดการขาย</label><input id="swal-won-value" class="swal2-input m-0 w-100" type="number" min="0.01" step="0.01" value="'+Number(card.data('value')).toFixed(2)+'"><label class="form-label d-block text-start mt-3" for="swal-won-date">วันที่ปิดการขาย</label><input id="swal-won-date" class="swal2-input m-0 w-100" type="date" max="'+today+'" value="'+today+'">',showCancelButton:true,confirmButtonText:'บันทึกปิดการขาย',cancelButtonText:'ยกเลิก',preConfirm:()=>{const value=document.getElementById('swal-won-value').value,date=document.getElementById('swal-won-date').value;if(!value||Number(value)<=0||!date){Swal.showValidationMessage('กรุณาระบุมูลค่าและวันที่ปิดการขาย');return false;}return{value,date};}});if(!result.isConfirmed)return;values.won_value=result.value.value;values.won_date=result.value.date;}else{const result=await Swal.fire({icon:'question',title:'เปลี่ยนเป็น '+stages[stage].label+'?',text:card.data('title'),showCancelButton:true,confirmButtonText:'เปลี่ยนขั้นตอน',cancelButtonText:'ยกเลิก'});if(!result.isConfirmed)return;}
        Swal.fire({title:'กำลังบันทึก...',allowOutsideClick:false,didOpen:()=>Swal.showLoading()});$.ajax({url:transitionUrl.replace('__ID__',card.data('opportunity-id')),method:'PATCH',data:{...values,_token:csrf}}).done(function(response){Swal.fire({icon:'success',title:response.msg,timer:1200,showConfirmButton:false});loadAll(false);}).fail(function(xhr){const errors=xhr.responseJSON?.errors,message=errors?Object.values(errors).flat()[0]:(xhr.responseJSON?.message||'เปลี่ยนขั้นตอนไม่สำเร็จ');Swal.fire({icon:'error',title:'เปลี่ยนขั้นตอนไม่สำเร็จ',text:message});});
    }
    form.on('submit',function(e){e.preventDefault();loadAll(true);});columns.on('click','.js-load-more',function(){const button=$(this),column=button.closest('.crm-kanban-column');load(column,Number(button.data('next-page')),true);}).on('click','.js-change-stage',function(){chooseStage($(this).closest('.crm-kanban-card'));}).on('dragstart','.crm-kanban-card[draggable="true"]',function(e){e.originalEvent.dataTransfer.effectAllowed='move';e.originalEvent.dataTransfer.setData('text/plain',$(this).data('opportunity-id'));$(this).addClass('is-dragging');}).on('dragend','.crm-kanban-card',function(){$(this).removeClass('is-dragging');columns.removeClass('is-drag-over');}).on('dragover',function(e){e.preventDefault();$(this).addClass('is-drag-over');}).on('dragleave',function(){$(this).removeClass('is-drag-over');}).on('drop',function(e){e.preventDefault();columns.removeClass('is-drag-over');const id=e.originalEvent.dataTransfer.getData('text/plain'),card=$('.crm-kanban-card[data-opportunity-id="'+id+'"]');transition(card,$(this).data('stage'));});
    window.addEventListener('popstate',()=>location.reload());loadAll(false);
});
</script>
@endpush
